from pathlib import Path
p=Path(__file__).with_name('workflow.html')
s=p.read_text(encoding='utf-8')
style='''<style>
:root{--ink:#183b43;--green:#137b69}body{max-width:none;margin:0;padding:32px 42px 60px 268px;background:#f4f7fa;color:var(--ink);font-size:14px}body>h1{font-size:28px;margin:0 0 8px;letter-spacing:-1px}body>p{color:#70818c}#sidebar{position:fixed;left:0;top:0;bottom:0;width:218px;background:#123c41;color:white;padding:28px 16px;box-sizing:border-box}#sidebar h2{padding:0 12px;font-size:24px;margin-bottom:5px}#sidebar p{padding:0 12px;color:#92b8b8;font-size:12px;margin-bottom:35px}#sidebar button{display:block;width:100%;text-align:left;background:transparent;color:#bbd2d3;margin:7px 0;padding:14px;border-radius:8px}#sidebar button.active{background:#245358;color:white}#sidebar .foot{position:absolute;bottom:24px;color:#93b4b7;padding:12px;font-size:12px}#status{position:static;border:1px solid #f0e4bf;background:#fff9e9;border-radius:9px;color:#8a722f;font-size:12px}section{box-shadow:0 3px 16px #20384a04;border:1px solid #e2e9ee;border-radius:14px;padding:26px;margin:18px 0}section h2{font-size:19px;margin-top:0}input,textarea,select{background:#fbfcfd;border:1px solid #dbe4e9;padding:12px;border-radius:7px;color:#294651;font:inherit}input:focus,textarea:focus,select:focus{outline:2px solid #91d0c0}button{cursor:pointer;background:#147d69;font:inherit;font-weight:600;padding:12px 18px}button:hover{filter:brightness(1.08)}#dashboard .hero{background:linear-gradient(110deg,#e3f3ed,#edf6fb);border:1px solid #d6e9e3;padding:26px;border-radius:14px;margin-top:22px;display:flex;justify-content:space-between;align-items:center}.hero h2{font-size:25px;margin:0 0 10px}.hero p{color:#5f7b7d}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.metric{background:white;padding:22px;border:1px solid #e1e8ed;border-radius:12px}.metric b{display:block;font-size:30px;margin:10px 0}.metric span{font-size:12px;color:#6e8590}.dashboard-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:20px}.step{padding:15px 0;border-bottom:1px solid #edf1f4;display:flex;justify-content:space-between}.badge{font-size:11px;background:#e5f4ed;color:#237658;padding:5px 8px;border-radius:5px}.bar{height:9px;border-radius:8px;background:#e9eff3;overflow:hidden}.bar i{display:block;height:100%;background:#23a38b}#report{white-space:normal}#report pre{white-space:pre-wrap}table{border-collapse:collapse;width:100%}td,th{padding:13px;border-bottom:1px solid #edf0f4;text-align:left}#presentation:fullscreen{background:#123c41;color:white;padding:7vw;box-sizing:border-box;font-size:26px;display:flex;flex-direction:column;justify-content:center}#presentation:fullscreen pre{font:inherit;line-height:1.8}.student-mode{padding:30px;max-width:760px;margin:auto}.student-mode #sidebar{display:none}@media(max-width:900px){body{padding:22px}#sidebar{position:static;width:auto;border-radius:12px;margin-bottom:20px}#sidebar button{display:inline-block;width:auto}#sidebar p,#sidebar .foot{display:none}.metrics{grid-template-columns:repeat(2,1fr)}.dashboard-grid{grid-template-columns:1fr}.hero{flex-direction:column;align-items:flex-start!important}}
</style>'''
script='''<script>
let view=0;
const sidebar=document.createElement('aside');sidebar.id='sidebar';sidebar.innerHTML='<h2>知序<span style="color:#65cfb2">.</span></h2><p>TEACHING WORKSPACE</p>'+['◈　教学概览','▤　教材资料','✎　班级与备课','▷　课堂教学','▥　作业与学情'].map((s,i)=>`<button onclick="switchView(${i})" id="nav${i}">${s}</button>`).join('')+'<div class="foot">七年级 · 数学上册<br><br>本地工作台 / 开发版</div>';document.body.prepend(sidebar);
const dashboard=document.createElement('div');dashboard.id='dashboard';$('teacher').prepend(dashboard);
function switchView(n){view=n;[...$('teacher').children].forEach((e,i)=>e.hidden=i!==n);for(let i=0;i<5;i++)$('nav'+i).classList.toggle('active',i===n);window.scrollTo(0,0)}
function drawDashboard(){let count=k=>records.filter(r=>r.kind===k).length,subs=records.filter(r=>r.kind==='submission'),a=records.find(r=>r.kind==='assignment'),cl=records.find(r=>r.kind==='class'),submitted=a?subs.filter(s=>s.assignment===a.id).length:0,total=cl?.students.length||0;dashboard.innerHTML=`<div class="hero"><div><h2>每一节课，都有清晰的下一步</h2><p>围绕教材组织备课，用课堂与作业反馈调整教学。</p><span class="badge">人教版七年级数学上册 · 教材版次待核实</span></div><button onclick="loadDemo()">＋ 加载完整模拟班级</button></div><div class="metrics">${[['教材材料',count('material'),'带出处的章节记录'],['已审核教案',count('lesson'),'可进入课堂演示'],['课堂与作业',count('assignment'),'已发布检测与作业'],['答题记录',subs.length,'匿名学生模拟或录入']].map(x=>`<div class="metric">${x[0]}<b>${x[1]}</b><span>${x[2]}</span></div>`).join('')}</div><div class="dashboard-grid"><section><h2>从这里开始体验</h2>${[['查看教材依据','材料及来源',1],['打开已审核教案','40分钟示例课堂',2],['进入课堂演示','展示与随堂检测',3],['查看班级反馈','正确率及缺交',4]].map(x=>`<div class="step"><div><b>${x[0]}</b><p style="color:#86959e;margin:7px 0">${x[1]}</p></div><button onclick="switchView(${x[2]})">进入 →</button></div>`).join('')}</section><section><h2>当前班级提交概况</h2><p>${esc(cl?.name||'尚未创建班级')}</p><b style="font-size:38px">${submitted}<span style="font-size:15px;color:#84939d"> / ${total} 人</span></b><p>最新一份检测 / 作业的提交情况</p><div class="bar"><i style="width:${total?submitted/total*100:0}%"></i></div><p style="color:#87969e">加载演示后包含12名学生、10人提交、2人缺交，可直接查看学情。</p><div style="background:#fff8e8;padding:16px;border-radius:8px">模拟内容均为自编测试资料，不是官方教材原文。</div></section></div>`}
const originalRefresh=refresh;refresh=async function(){await originalRefresh();drawDashboard();let l=records.find(r=>r.id===$('lessons').value);if(l&&!$('lesson').value)$('lesson').value=l.text;};
async function loadDemo(){await run(async()=>{await call('demo',{});});if(records.some(r=>r.kind==='class')){$('status').textContent='模拟场景已就绪：12名学生、1份教案、2份检测/作业；每份10人提交、2人缺交。';switchView(0)}}
report=function(){run(async()=>{lastReport=await call('report',{assignment:chosen('assignments').id});let a=lastReport.analysis;let summary=a?.summary||[];$('report').innerHTML=`<h3>班级学习反馈</h3><div class="metrics"><div class="metric">已提交<b>${a?.students||0}</b></div><div class="metric">未提交<b>${lastReport.missing.length}</b></div><div class="metric">答题记录<b>${a?.submissions||0}</b></div><div class="metric">知识点<b>${summary.length}</b></div></div><table><thead><tr><th>知识点</th><th>正确率</th><th>正确 / 提交</th></tr></thead><tbody>${summary.map(s=>`<tr><td>${esc(s.topic)}</td><td><b>${s.rate}%</b><div class="bar"><i style="width:${s.rate}%"></i></div></td><td>${s.correct} / ${s.total}</td></tr>`).join('')}</tbody></table><h3>缺交名单</h3><p>${esc(lastReport.missing.join('、')||'全部已交')}</p><h3>后续教学建议</h3>${summary.map(s=>`<p>${esc(s.suggestion)}</p>`).join('')}<small>基于最终答案统计；具体错因仍需查看解题过程。</small><details><summary>查看逐题结果</summary><table><tr><th>学生</th><th>题目</th><th>结果</th></tr>${(a?.details||[]).map(d=>`<tr><td>${esc(d.student)}</td><td>${esc(d.question_id)}</td><td>${d.correct?'✓ 正确':'需复习'}</td></tr>`).join('')}</table></details>`})};
if(aid){document.body.classList.add('student-mode');dashboard.hidden=true}else{switchView(0);refresh()}
</script>'''
if 'TEACHING WORKSPACE' not in s:
    s=s.replace('</style>', '</style>'+style,1)+script
    p.write_text(s,encoding='utf-8')
